use xrai_eval::context_spike::{Case,Meter,Store};
struct Control {calls:usize,slow_on:Option<usize>}
impl Meter for Control {
 fn profile(&self)->&str {"independent-byte-control-v1"}
 fn tokens(&mut self, b:&[u8])->Result<usize,String>{
