 let file_error=store.expand(&d.manifest.context_id,&ids,file_limits,1,&mut meter).err().unwrap();
 assert_eq!(file_error,"work_limit:expansion_sources");
 let mut source_limits=c.request.limits.clone();source_limits.max_source_bytes=1;
 let source_error=store.expand(&d.manifest.context_id,&ids,source_limits,1,&mut meter).err().unwrap();
 assert_eq!(source_error,"work_limit:expansion_sources");
 let mut lim=c.request.limits.clone();lim.deadline_ms=100;
 meter.calls=0;
 store.expand(&d.manifest.context_id,&ids,lim.clone(),1,&mut meter).unwrap();
 let dry_calls=meter.calls;
 meter.calls=0;meter.slow_on=Some(dry_calls);
 let start=Instant::now();
 let deadline_error=store.expand(&d.manifest.context_id,&ids,lim,1,&mut meter).err().unwrap();
 assert_eq!(deadline_error,"work_limit:deadline");
 assert!(start.elapsed().as_millis()>=150);
 println!("{}",serde_json::json!({"C01":{"max_files":file_error,"max_source_bytes":source_error},"C02":{"dry_meter_calls":dry_calls,"delayed_call":meter.calls,"elapsed_ms":start.elapsed().as_millis(),"error":deadline_error,"byte_control_not_billed_tokens":true},"C03":{"normalized_typed_request_identical":true,"anchors":d.manifest.normalized_request.anchors.len(),"p2":d.manifest.normalized_request.p2}}));
